}

#[test]
fn derived_damage_requires_separate_recovery_and_preserves_the_exact_recipe() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().join("archive");
    let mut s = service(&root);
    append(&mut s, 1);
    let issuer = s.issuer();
