        r = self.b[self.i:self.i + n]; self.i += n; assert len(r) == n; return r
    def arg(self, low):
        if low < 24: return low
        return int.from_bytes(self.take({24: 1, 25: 2, 26: 4, 27: 8}[low]), 'big')
